#!/bin/bash
# Uninstall script for Fing Desktop
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling Fing Desktop..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping Fing Desktop if running..."
pkill -f "Fing Desktop" 2>/dev/null || true

# Unload service com.fing.service
echo "Unloading service com.fing.service..."
launchctl unload -w /Library/LaunchAgents/com.fing.service.plist 2>/dev/null || true
launchctl unload -w /Library/LaunchDaemons/com.fing.service.plist 2>/dev/null || true
launchctl unload -w ~/Library/LaunchAgents/com.fing.service.plist 2>/dev/null || true

# Remove /Applications/Fing.app
echo "Removing /Applications/Fing.app..."
if [ -d "/Applications/Fing.app" ]; then
    rm -rf "/Applications/Fing.app" 2>/dev/null || true
elif [ -f "/Applications/Fing.app" ]; then
    rm -f "/Applications/Fing.app" 2>/dev/null || true
fi

# Remove $HOME/Library/Application Support/Fing
echo "Removing $HOME/Library/Application Support/Fing..."
if [ -d "$HOME/Library/Application Support/Fing" ]; then
    rm -rf "$HOME/Library/Application Support/Fing" 2>/dev/null || true
elif [ -f "$HOME/Library/Application Support/Fing" ]; then
    rm -f "$HOME/Library/Application Support/Fing" 2>/dev/null || true
fi

# Remove $HOME/Library/Logs/Fing
echo "Removing $HOME/Library/Logs/Fing..."
if [ -d "$HOME/Library/Logs/Fing" ]; then
    rm -rf "$HOME/Library/Logs/Fing" 2>/dev/null || true
elif [ -f "$HOME/Library/Logs/Fing" ]; then
    rm -f "$HOME/Library/Logs/Fing" 2>/dev/null || true
fi

# Remove $HOME/Library/Preferences/com.fing.app.plist
echo "Removing $HOME/Library/Preferences/com.fing.app.plist..."
if [ -d "$HOME/Library/Preferences/com.fing.app.plist" ]; then
    rm -rf "$HOME/Library/Preferences/com.fing.app.plist" 2>/dev/null || true
elif [ -f "$HOME/Library/Preferences/com.fing.app.plist" ]; then
    rm -f "$HOME/Library/Preferences/com.fing.app.plist" 2>/dev/null || true
fi

# Remove $HOME/Library/Saved Application State/com.fing.app.savedState
echo "Removing $HOME/Library/Saved Application State/com.fing.app.savedState..."
if [ -d "$HOME/Library/Saved Application State/com.fing.app.savedState" ]; then
    rm -rf "$HOME/Library/Saved Application State/com.fing.app.savedState" 2>/dev/null || true
elif [ -f "$HOME/Library/Saved Application State/com.fing.app.savedState" ]; then
    rm -f "$HOME/Library/Saved Application State/com.fing.app.savedState" 2>/dev/null || true
fi

echo "Uninstallation complete!"
exit 0
